import api from '../utils/api';
import { PRODUCTS, CATEGORIES } from '../utils/dummyData';

// Helper to format dummy products to match the expected schema
const formatDummyProduct = (p) => {
  if (!p) return null;
  return {
    ...p,
    category: {
      _id: p.category,
      name: p.category
    },
    images: [{ url: p.image }],
    vendor: {
      storeName: p.vendor || 'ShopZone Official'
    },
    totalReviews: p.reviews || 0 // Home.js uses totalReviews for trending sort
  };
};

export const productService = {
  async getProducts(params = {}) {
    try {
      const response = await api.get('/products', { params });
      return response.data.data;
    } catch (error) {
      console.warn('Backend unavailable, using dummy products');

      let filtered = [...PRODUCTS];

      if (params.category && params.category !== 'All') {
        filtered = filtered.filter(p => 
          p.category === params.category || p.category?.toLowerCase() === params.category?.toLowerCase()
        );
      }

      if (params.search) {
        const q = params.search.toLowerCase();
        filtered = filtered.filter(p => 
          p.name.toLowerCase().includes(q) || 
          p.description?.toLowerCase().includes(q) ||
          p.brand?.toLowerCase().includes(q)
        );
      }

      if (params.minPrice) filtered = filtered.filter(p => p.price >= params.minPrice);
      if (params.maxPrice) filtered = filtered.filter(p => p.price <= params.maxPrice);
      if (params.minRating) filtered = filtered.filter(p => p.rating >= params.minRating);
      if (params.brand) filtered = filtered.filter(p => p.brand === params.brand);

      // Sorting
      if (params.sort === 'price_asc') filtered.sort((a, b) => a.price - b.price);
      else if (params.sort === 'price_desc') filtered.sort((a, b) => b.price - a.price);
      else if (params.sort === 'rating') filtered.sort((a, b) => b.rating - a.rating);

      const limit = params.limit || 20;
      const page = params.page || 1;
      const start = (page - 1) * limit;
      const paginated = filtered.slice(start, start + limit);

      return { 
        items: paginated.map(formatDummyProduct), 
        pagination: {
          page,
          totalPages: Math.ceil(filtered.length / limit) || 1,
          total: filtered.length
        }
      };
    }
  },
  async getProductById(id) {
    try {
      const response = await api.get(`/products/${id}`);
      return response.data.data.item;
    } catch (error) {
      const p = PRODUCTS.find(p => p._id === String(id));
      return formatDummyProduct(p);
    }
  },
  async getCategories() {
    try {
      const response = await api.get('/categories');
      return response.data.data.items;
    } catch (error) {
      return CATEGORIES.map(c => ({ 
        ...c, 
        _id: c.name,
        icon: c.icon || '•'
      }));
    }
  }
};
